class Till(private var cash: Int) {
    private fun note(text: String) {
        println("note: " + text)
    }

    fun take(amount: Int) {
        if (amount <= cash) {
            cash = cash - amount
            note("took " + amount)
        } else {
            note("not enough")
        }
    }
}

fun main() {
    val till = Till(30)
    till.take(20)
    till.take(20)
}

